	CreateSignature(context.Context, *CreateSignatureRequest) (*CreateSignatureResponse, error)
	GetSignature(context.Context, *GetSignatureRequest) (*GetSignatureResponse, error)
	ListSignatures(context.Context, *ListSignaturesRequest) (*ListSignaturesResponse, error)
	UpdateSignature(context.Context, *UpdateSignatureRequest) (*UpdateSignatureResponse, error)
	DeleteSignature(context.Context, *DeleteSignatureRequest) (*DeleteSignatureResponse, error)
	SetDefaultSignature(context.Context, *SetDefaultSignatureRequest) (*SetDefaultSignatureResponse, error)
	// CRM linking operations
	GetEmailContactLinks(context.Context, *GetEmailContactLinksRequest) (*GetEmailContactLinksResponse, error)
	LinkEmailToContact(context.Context, *LinkEmailToContactRequest) (*LinkEmailToContactResponse, error)
	UnlinkEmailFromContact(context.Context, *UnlinkEmailFromContactRequest) (*UnlinkEmailFromContactResponse, error)
	GetContactEmails(context.Context, *GetContactEmailsRequest) (*GetContactEmailsResponse, error)
	// Sync operations
	TriggerSync(context.Context, *TriggerSyncRequest) (*TriggerSyncResponse, error)
	GetSyncStatus(context.Context, *GetSyncStatusRequest) (*GetSyncStatusResponse, error)
	SetReadFlag(context.Context, *SetReadFlagRequest) (*SetReadFlagResponse, error)
	// Attachment operations
	UploadAttachment(context.Context, *UploadAttachmentRequest) (*UploadAttachmentResponse, error)
	GetAttachmentDownloadURL(context.Context, *GetAttachmentDownloadURLRequest) (*GetAttachmentDownloadURLResponse, error)
	// Contact import/export
