	UpdateEmailLabel(context.Context, *UpdateEmailLabelRequest) (*UpdateEmailLabelResponse, error)
	DeleteEmailLabel(context.Context, *DeleteEmailLabelRequest) (*DeleteEmailLabelResponse, error)
